// Rule-based QC checks for autogenerated image/alt-text captions.
// Catches placeholder captions, length outliers, and missing required
// keywords before a caption ships. Does not look at the image itself.

const BANNED_PHRASES = ["image of", "picture of", "no caption available", "untitled image"];
const MIN_WORDS = 3;
const MAX_WORDS = 25;

function containsPhrase(text: string, phrase: string): boolean {
  const normalized = phrase.toLowerCase().trim().split(/\s+/).join(" ");
  if (!normalized) return false;
  const escaped = normalized.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])`, "u").test(text);
}

export function checkCaption(caption: string, requiredKeywords: string[] = []) {
  const lowered = caption.toLowerCase().trim().split(/\s+/).join(" ");
  const reasons: string[] = [];
  const wordCount = caption.trim().split(/\s+/).filter(Boolean).length;
  if (wordCount < MIN_WORDS) reasons.push("too_short");
  if (wordCount > MAX_WORDS) reasons.push("too_long");
  for (const phrase of BANNED_PHRASES) if (containsPhrase(lowered, phrase)) reasons.push(`banned_phrase:${phrase}`);
  const missing = requiredKeywords.filter((kw) => !containsPhrase(lowered, kw));
  if (missing.length) reasons.push("missing_keywords:" + missing.join(","));
  return { passed: reasons.length === 0, reasons };
}

export interface EvalCase {
  caption: string;
  required: string[];
  passed: boolean;
}

export const EVAL_CASES: EvalCase[] = [
  { caption: "A golden retriever running across a sunny beach.", required: [], passed: true },
  { caption: "image of a dog", required: [], passed: false },
  { caption: "A cat.", required: [], passed: false },
  { caption: "A red sports car parked outside a brick building.", required: ["car"], passed: true },
  { caption: "A red sports car parked outside a brick building.", required: ["truck"], passed: false },
];

export function evaluateAll() {
  const correct = EVAL_CASES.filter((c) => checkCaption(c.caption, c.required).passed === c.passed).length;
  return { cases: EVAL_CASES.length, accuracy: correct / EVAL_CASES.length };
}
